import Groq from "groq-sdk";
import type { Request, Response } from "express";

export interface SosAnalysisInput {
  senderId: string;
  senderName: string;
  location: { latitude: number; longitude: number };
  content?: string;
  routingPath: string[];
  networkHealth: {
    onlineNodes: number;
    totalNodes: number;
    activeConnections: number;
    averageLatencyMs: number;
  };
}

export interface SosAnalysis {
  summary: string;
  provider: string;
}

/**
 * Crisis analysis for an incoming SOS, generated by Groq. Never throws —
 * if the API is unreachable a deterministic triage template is returned so
 * the SOS pipeline (and the demo) can never be taken down by the AI step.
 */
export async function generateSosAnalysis(input: SosAnalysisInput): Promise<SosAnalysis> {
  const { location, networkHealth } = input;

  const fallback: SosAnalysis = {
    provider: "offline-triage",
    summary: [
      `SOS from ${input.senderName} at ${location.latitude.toFixed(4)}, ${location.longitude.toFixed(4)}. ` +
        `Mesh: ${networkHealth.onlineNodes}/${networkHealth.totalNodes} nodes online, uplinked over ${Math.max(input.routingPath.length - 1, 1)} hop(s).`,
      "1. Dispatch the nearest field team to the coordinates and confirm visual contact.",
      "2. Keep the relay nodes on the SOS routing path powered — they are the victim's only comms channel.",
      "3. Establish two-way contact over the mesh to triage medical needs before arrival.",
    ].join("\n"),
  };

  if (!process.env.GROQ_API_KEY) {
    console.warn("GROQ_API_KEY missing — using offline triage summary for SOS");
    return fallback;
  }

  try {
    const groq = new Groq({ apiKey: process.env.GROQ_API_KEY, timeout: 12000, maxRetries: 1 });
    const completion = await groq.chat.completions.create({
      model: "llama-3.1-8b-instant",
      temperature: 0.4,
      max_tokens: 350,
      messages: [
        {
          role: "system",
          content:
            "You are a crisis management AI for a disaster-relief mesh network. " +
            "Summarize the incoming SOS signal in 1-2 sentences, then provide exactly 3 numbered, " +
            "immediate tactical recommendations for first responders. Be specific to the data given. " +
            "Total response under 130 words. No preamble, no markdown headings.",
        },
        {
          role: "user",
          content: [
            `SOS SIGNAL RECEIVED`,
            `Sender: ${input.senderName} (node "${input.senderId}")`,
            `Coordinates: ${location.latitude.toFixed(5)}, ${location.longitude.toFixed(5)} (Bengaluru, India)`,
            `Attached message: ${input.content ?? "none"}`,
            `Mesh routing path to Cisco gateway: ${input.routingPath.join(" -> ")}`,
            `Network health: ${networkHealth.onlineNodes}/${networkHealth.totalNodes} nodes online, ` +
              `${networkHealth.activeConnections} active links, avg latency ${networkHealth.averageLatencyMs}ms`,
          ].join("\n"),
        },
      ],
    });

    const summary = completion.choices[0]?.message?.content?.trim();
    if (!summary) return fallback;
    return { summary, provider: `groq/llama-3.1-8b-instant` };
  } catch (error) {
    console.error("Groq SOS analysis failed, using offline triage:", error);
    return fallback;
  }
}

export async function groqChatHandler(req: Request, res: Response) {
  try {
    const { messages } = req.body;
    
    if (!process.env.GROQ_API_KEY) {
      return res.status(500).json({ error: "GROQ_API_KEY is not configured in .env" });
    }

    const groq = new Groq({ apiKey: process.env.GROQ_API_KEY });
    
    const systemMessage = {
      role: "system",
      content: "You are the Aid-Response Crisis AI. A highly intelligent assistant helping operators during disaster situations. You provide concise, actionable, and accurate emergency response advice based on the Disaster Network Simulator context."
    };

    const chatCompletion = await groq.chat.completions.create({
      messages: [systemMessage, ...messages],
      model: "llama-3.1-8b-instant",
      temperature: 0.5,
      max_tokens: 1024,
    });

    const reply = chatCompletion.choices[0]?.message?.content;
    res.json({ reply });
  } catch (error: any) {
    console.error("Groq AI Error:", error);
    res.status(500).json({ error: error.message || "Failed to generate AI response" });
  }
}
